  function loadChampions(){
    if (championsLoading) return championsLoading;
    championsLoading = (async () => {
      const versions = await (await fetch("https://ddragon.leagueoflegends.com/api/versions.json")).json();
      DDRAGON_VERSION = versions[0];
      const data = await (await fetch("https://ddragon.leagueoflegends.com/cdn/" + DDRAGON_VERSION + "/data/en_US/champion.json")).json();
      CHAMPIONS = Object.values(data.data)
        .map(c => ({ id: c.id, name: c.name, tags: c.tags || [], info: c.info || {} }))
        .sort((a,b) => a.name.localeCompare(b.name));
      return CHAMPIONS;
    })().catch(e => {
      console.error("Champion-Liste konnte nicht von Data Dragon geladen werden", e);
      championsLoading = null;
      return [];
    });
    return championsLoading;
  }

  // ---- Einfaches Hash-Routing: "#player/<id>" zeigt die Spielerseite ----
  function getRoute(){
    const hash = location.hash || "";
    const m = hash.match(/^#player\/(.+)$/);
    if (m) return { view: "player", id: decodeURIComponent(m[1]) };
    const dm = hash.match(/^#draft\/(.+)$/);
    if (dm) return { view: "draft", id: decodeURIComponent(dm[1]) };
    if (hash === "#champions") return { view: "champions" };
    if (hash === "#manage") return { view: "manage" };
    if (hash === "#calendar") return { view: "calendar" };
    if (hash === "#impressum") return { view: "legal", kind: "impressum" };
    if (hash === "#datenschutz") return { view: "legal", kind: "datenschutz" };
    return { view: "main" };
  }

