  function timeSfx(){ return UI.lang() === "en" ? "" : " Uhr"; }
  function fmtDate(iso){
    if (!iso) return "Datum offen";
    const d = new Date(iso + "T00:00:00");
    if (isNaN(d)) return iso;
    return d.toLocaleDateString(UI.locale(), { weekday: "short", day: "2-digit", month: "2-digit" });
  }
  // Liefert { weekday, dm } getrennt, damit "dd.mm." fett dargestellt werden kann
  function fmtDateParts(iso){
    if (!iso) return { weekday: "", dm: "Datum offen" };
    const d = new Date(iso + "T00:00:00");
    if (isNaN(d)) return { weekday: "", dm: iso };
    const weekday = d.toLocaleDateString(UI.locale(), { weekday: "short" });
    const dm = d.toLocaleDateString(UI.locale(), { day: "2-digit", month: "2-digit" });
    return { weekday, dm };
  }

  // Format für Terminvorschläge: "dd.mm." optional gefolgt von " hh:mm" (Uhrzeit nicht zwingend)
  const PROPOSAL_DATE_RE = /^(\d{1,2})\.(\d{1,2})\.\s*(?:(\d{1,2}):(\d{2}))?$/;
  function parseProposalDate(text){
    const m = (text || "").trim().match(PROPOSAL_DATE_RE);
    if (!m) return null;
    const day = parseInt(m[1], 10), month = parseInt(m[2], 10);
    if (day < 1 || day > 31 || month < 1 || month > 12) return null;
    const hasTime = m[3] !== undefined;
    const hour = hasTime ? parseInt(m[3], 10) : null;
    const min = hasTime ? parseInt(m[4], 10) : null;
    if (hasTime && (hour > 23 || min > 59)) return null;
    return { day, month, hour, min, hasTime };
  }
  // Sortierschlüssel für die chronologische Sortierung der Terminvorschläge; null = kein erkennbares Datum (bleibt hinten)
  function proposalSortKey(text){
    const d = parseProposalDate(text);
    if (!d) return null;
    const minutes = d.hasTime ? d.hour * 60 + d.min : -1; // ohne Uhrzeit zuerst am selben Tag
    return d.month * 46080 + d.day * 1440 + minutes; // 32 Tage * 1440 Minuten als sichere Basis
  }
  function formatDateAsProposal(iso, time){
    if (!iso) return "";
    const parts = iso.split("-");
    return parts[2] + "." + parts[1] + "." + (time ? " " + time : "");
  }

  function playerById(id){
    if (id === ADMIN_ID) return { id: ADMIN_ID, name: adminName(), role: "admin", avatar: (state && state.adminAvatar) || "" };
    return (state.players || []).find(p => p.id === id);
  }

  // Alle Änderungen laufen über diese Funktion statt über ein einfaches "ganzes Dokument
  // überschreiben". Sie liest per Firestore-Transaktion immer erst den aktuellsten Stand vom
  // Server, wendet die Änderung darauf an und schreibt sie zurück. Schreibt in der Zwischenzeit
  // jemand anderes, wiederholt Firestore die Transaktion automatisch mit dem neuen Stand - so
  // gehen gleichzeitige Änderungen von zwei Leuten nicht mehr verloren.
  // Änderung sofort lokal anwenden und anzeigen (fühlt sich instant an), danach im Hintergrund
  // speichern. Bewusst wieder ohne Transaktion - die hat bei jeder Aktion erst einen Lese-Umweg
  // zum Server gebraucht, bevor überhaupt etwas zu sehen war, das hat sich spürbar träge angefühlt.
  // ---------- Discord-Benachrichtigungen per Webhook (Einstellungen liegen im Team-Dokument) ----------
  // ---- Discord-Modus: Einstellungen und Versand laufen über die Cloud Function (Webhook liegt nur dort) ----
  const dcServer = { cfg: null, loading: false, members: null, membersLoading: false };
  async function callApi(path, method, body){
    try {
      const user = firebase.auth().currentUser;
      if (!user) return null;
      const token = await user.getIdToken();
      const r = await fetch(AUTH_CONFIG.apiBase + path, { method: method || "GET", headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" }, body: body ? JSON.stringify(body) : undefined });
      return r.ok ? await r.json() : null;
    } catch(e){ console.error("API-Fehler", path, e); return null; }
  }
  function discordCfg(){
    if (AUTH_CONFIG.discord) return { test: !!(dcServer.cfg && dcServer.cfg.testMode), url: state.discordOn ? "server" : "", role: "" };
    return {
      test: !!state.discordTestMode,
      url: String(state.discordTestMode ? state.discordTestWebhook : state.discordWebhook || "").trim(),
      role: (r => /^\d{5,25}$/.test(r) ? r : "")(String((state.discordTestMode ? state.discordTestRole : state.discordRole) || "").trim())
    };
  }
  function discordPost(payload){
    const c = discordCfg();
    if (!/^https:\/\/(canary\.|ptb\.)?discord(app)?\.com\/api\/webhooks\//.test(c.url)) return Promise.resolve(false);
    return fetch(c.url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) })
      .then(r => r.ok).catch(() => false);
  }
  function discordLang(){ return state.discordLang === "en" ? "en" : "de"; }
  function discordSend(embed, force){
    const c = discordCfg();
    if (typeof embed === "function") embed = embed(discordLang());
    const mention = c.role ? "<@&" + c.role + ">" : "@team";
    const pageUrl = location.href.split("#")[0];
    if (AUTH_CONFIG.discord){
      return callApi("/send", "POST", { username: teamTag() + " Planer", embed: Object.assign(/^https?:/.test(pageUrl) ? { url: pageUrl } : {}, embed) }).then(r => !!(r && r.ok));
    }
    return discordPost({
      username: teamTag() + " Planer",
      content: mention,
      allowed_mentions: c.role ? { roles: [c.role] } : { parse: [] },
      embeds: [Object.assign({ color: 0xff7a35 }, /^https?:/.test(pageUrl) ? { url: pageUrl } : {}, embed)]
    });
  }
  function discordNotify(kind, embed){
    discordSend(embed);   // embed darf eine Funktion (lang) => {title, description} sein
  }
  function mdTitle(md){ return teamTag() + " vs. " + (md.opponent || "?"); }
  function mdWhen(md, l){
    l = l || UI.lang();
    return (md.date ? new Date(md.date + "T00:00:00").toLocaleDateString(l === "en" ? "en-GB" : "de-DE", { weekday: "long", day: "2-digit", month: "2-digit" }) : UI.Tl("Datum offen", l)) + (md.time ? " · " + md.time + (l === "en" ? "" : " Uhr") : "");
  }

  async function mutateState(fn){
    const s = cloneState(state);
    fn(s);
    state = s;
    render();
    if (!dbRef) return;
    try {
      await dbRef.set(s);
    } catch(e){
      console.error("Speichern fehlgeschlagen", e);
      uiAlert("Speichern hat nicht geklappt. Prüfe die Internetverbindung bzw. die Firebase-Konfiguration.");
    }
  }

  function setAvailability(matchdayId, playerId, status){
    mutateState(s => {
      s.availability[matchdayId] = s.availability[matchdayId] || {};
      const cur = s.availability[matchdayId][playerId] || {};
      let newStatus = cur.status === status ? null : status;
      // note field only makes sense for "unsicher" / "kann nicht" – clear it once confirmed available
      let newNote = (newStatus === "yes") ? "" : (cur.note || "");
      s.availability[matchdayId][playerId] = Object.assign({ status: newStatus, note: newNote }, cur.lane ? { lane: cur.lane } : {});
    });
  }

  function setNote(matchdayId, playerId, note){
    mutateState(s => {
      s.availability[matchdayId] = s.availability[matchdayId] || {};
      const cur = s.availability[matchdayId][playerId] || {};
      s.availability[matchdayId][playerId] = Object.assign({ status: cur.status || null, note: note }, cur.lane ? { lane: cur.lane } : {});
    });
  }

  function setResult(matchdayId, us, them){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      md.result = { us: us, them: them };
      editingResults.delete(matchdayId);
    });
    const mdR = (state.matchdays || []).find(m => m.id === matchdayId);
    if (mdR) discordNotify("result", l => ({
      title: UI.Tl("Ergebnis: ", l) + mdTitle(mdR),
      description: "**" + us + ":" + them + "** " + UI.Tl(us === them ? "unentschieden" : (us > them ? "gewonnen" : "verloren"), l)
    }));
  }

  function clearResult(matchdayId){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      md.result = null;
      editingResults.delete(matchdayId);
    });
  }

  function setChampionTier(playerId, champId, tier){
    mutateState(s => {
      const p = s.players.find(p => p.id === playerId);
      if (!p) return;
      p.tierlist = p.tierlist || {};
      p.tierlist[champId] = tier;
    });
  }
  // Reihenfolge innerhalb einer Tier-Reihe: gespeicherte Reihenfolge, bereinigt um Champions, die nicht
  // mehr in dieser Reihe sind, plus neue Champions dieser Reihe automatisch ans Ende angehängt.
  function tierOrderFor(p, t){
    const stored = (p.tierOrder && Array.isArray(p.tierOrder[t])) ? p.tierOrder[t] : [];
    const actual = Object.keys(p.tierlist || {}).filter(id => p.tierlist[id] === t);
    const ordered = stored.filter(id => actual.includes(id));
    actual.forEach(id => { if (!ordered.includes(id)) ordered.push(id); });
    return ordered;
  }
  // Champion gezielt in eine Tier-Reihe (um)sortieren - vor beforeChampId einsortieren, ohne Ziel ans Ende
  // Committed nach einem Live-Sortieren den fertigen Zustand aller drei Tier-Reihen auf einmal
  // (die gezogene Karte kann während einer Geste die Reihe gewechselt haben).
  function commitTierOrder(playerId, orderByTier){
    mutateState(s => {
      const p = s.players.find(pl => pl.id === playerId);
      if (!p) return;
      p.tierlist = p.tierlist || {};
      p.tierOrder = p.tierOrder || {};
      TIERS.forEach(t => {
        (orderByTier[t] || []).forEach(id => { p.tierlist[id] = t; });
        p.tierOrder[t] = orderByTier[t] || [];
      });
    });
  }
  function removeChampionTier(playerId, champId){
    mutateState(s => {
      const p = s.players.find(p => p.id === playerId);
      if (!p || !p.tierlist) return;
      delete p.tierlist[champId];
    });
  }

  function addReschedule(matchdayId, reason){
    const me = getMe();
    if (!me){ uiAlert(needMeMsg()); return; }
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      md.reschedule = md.reschedule || [];
      md.reschedule.push({ id: uid("resched"), playerId: me, reason: reason || "", at: Date.now() });
    });
  }

  // Neue Terminvorschläge seit dem letzten Ping (bzw. seit Anlage des Spieltags); ältere Vorschläge ohne Zeitstempel und
  // der beim Übernehmen "abgelöste" alte Termin zählen nie als neu.
  const PING_COOLDOWN_MS = 60000;
  function pendingProposals(md){
    const since = md.pingAt || md.createdAt || 0;
    return (md.reschedule || []).filter(r => r.at && r.at > since);
  }
  function pingCooldownLeft(md){
    return md.pingAt ? Math.max(0, PING_COOLDOWN_MS - (Date.now() - md.pingAt)) : 0;
  }
  function sendProposalPing(matchdayId){
    const md = (state.matchdays || []).find(m => m.id === matchdayId);
    if (!md || pingCooldownLeft(md) > 0) return;
    const list = pendingProposals(md);
    if (!list.length) return;
    const snap = Object.assign({}, md);
    mutateState(s => {
      const m = s.matchdays.find(x => x.id === matchdayId);
      if (m) m.pingAt = Date.now();
    });
    discordNotify("proposal", l => ({
      title: UI.Tl("Neue Terminvorschläge: ", l) + mdTitle(snap),
      description: list.map(r => {
        const p = playerById(r.playerId);
        return "• **" + (r.reason || "–") + "**" + (p && p.name ? " (" + p.name + ")" : "");
      }).join("\n") + "\n" + (l === "en" ? "(currently: " : "(bisher: ") + mdWhen(snap, l) + ")"
    }));
  }

  function removeReschedule(matchdayId, proposalId){
    const me = getMe();
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      const entry = (md.reschedule || []).find(r => (r.id || r.playerId) === proposalId);
      if (!entry) return;
      if (entry.playerId !== me && !isAdmin()){ uiAlert("Nur die Person, die den Vorschlag gemacht hat, kann ihn zurückziehen."); return; }
      md.reschedule = (md.reschedule || []).filter(r => (r.id || r.playerId) !== proposalId);
    });
  }

  // Terminvorschlag übernehmen: der Vorschlag wird zum offiziellen Termin, der bisherige offizielle
  // Termin wird dafür zu einem neuen Vorschlag und übernimmt dessen bisherige Abstimmung (3-stufig ->
  // 2-stufig: "unsicher" wird zu einem Daumen-runter, bleibt aber mit "?" hinter dem Namen erkennbar;
  // Notizen wandern in beiden Richtungen mit).
  function swapMatchdayDate(matchdayId, proposalId){
    const md = (state.matchdays || []).find(m => m.id === matchdayId);
    if (!md) return;
    const r = (md.reschedule || []).find(x => (x.id || x.playerId) === proposalId);
    if (!r) return;
    const parsed = parseProposalDate(r.reason);
    if (!parsed || !parsed.hasTime){
      uiAlert("Für die Übernahme wird das Format dd.mm. hh:mm benötigt (mit Uhrzeit). Bitte den Vorschlagstext entsprechend anpassen und nochmal versuchen.");
      return;
    }
    const me = getMe();
    const before = Object.assign({}, md);
    const year = new Date().getFullYear();
    const newDate = year + "-" + String(parsed.month).padStart(2, "0") + "-" + String(parsed.day).padStart(2, "0");
    const newTime = String(parsed.hour).padStart(2, "0") + ":" + String(parsed.min).padStart(2, "0");

    mutateState(s => {
      const smd = s.matchdays.find(m => m.id === matchdayId);
      if (!smd) return;
      const sr = (smd.reschedule || []).find(x => (x.id || x.playerId) === proposalId);
      if (!sr) return;

      const oldDate = smd.date, oldTime = smd.time;
      const oldAvail = (s.availability && s.availability[matchdayId]) || {};

      // Bisherige Hauptabstimmung (3-stufig) -> Stimmen für den neuen (jetzt alten) Terminvorschlag
      const demotedVotes = {}, demotedMeta = {};
      Object.keys(oldAvail).forEach(pid => {
        const entry = oldAvail[pid] || {};
        if (entry.status === "yes") demotedVotes[pid] = "yes";
        else if (entry.status === "no") demotedVotes[pid] = "no";
        else if (entry.status === "maybe"){ demotedVotes[pid] = "no"; demotedMeta[pid] = { maybe: true }; }
        if (entry.note){ demotedMeta[pid] = demotedMeta[pid] || {}; demotedMeta[pid].note = entry.note; }
      });

      // Stimmen des übernommenen Vorschlags -> neue Hauptabstimmung (inkl. Rückwandlung "?" -> unsicher)
      const newAvail = {};
      Object.keys(sr.votes || {}).forEach(pid => {
        const meta = (sr.voteMeta && sr.voteMeta[pid]) || {};
        const status = meta.maybe ? "maybe" : (sr.votes[pid] === "yes" ? "yes" : "no");
        newAvail[pid] = { status: status, note: meta.note || "" };
      });

      Object.keys(oldAvail).forEach(pid => { if (oldAvail[pid] && oldAvail[pid].lane){ newAvail[pid] = newAvail[pid] || { status: null, note: "" }; newAvail[pid].lane = oldAvail[pid].lane; } });
      smd.date = newDate;
      smd.time = newTime;
      s.availability[matchdayId] = newAvail;

      smd.reschedule = (smd.reschedule || []).filter(x => (x.id || x.playerId) !== proposalId);
      if (oldDate){
        smd.reschedule.push({
          id: uid("resched"),
          playerId: sr.playerId || me,
          reason: formatDateAsProposal(oldDate, oldTime),
          votes: demotedVotes,
          voteMeta: demotedMeta,
          requestedWithOpponent: false,
          accepted: false,
          rejected: false
        });
      }
    });
    const after = (state.matchdays || []).find(m => m.id === matchdayId);
    if (after) discordNotify("date", l => ({
      title: UI.Tl("Neuer Termin: ", l) + mdTitle(after),
      description: "**" + mdWhen(after, l) + "**" + (before.date ? "\n" + (l === "en" ? "(previously: " : "(vorher: ") + mdWhen(before, l) + ")" : "")
    }));
  }

  function voteOnReschedule(matchdayId, proposalId, voterId, vote){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      const r = (md.reschedule || []).find(r => (r.id || r.playerId) === proposalId);
      if (!r) return;
      r.votes = r.votes || {};
      if (r.votes[voterId] === vote) delete r.votes[voterId];
      else r.votes[voterId] = vote;
    });
  }

  function setRescheduleStatus(matchdayId, proposalId, field, value){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      const r = (md.reschedule || []).find(r => (r.id || r.playerId) === proposalId);
      if (!r) return;
      r[field] = value;
    });
  }
  // Ergebnis beim Gegner: offen / angenommen / abgelehnt (schließen sich gegenseitig aus)
  function setRescheduleOutcome(matchdayId, proposalId, outcome){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === matchdayId);
      if (!md) return;
      const r = (md.reschedule || []).find(r => (r.id || r.playerId) === proposalId);
      if (!r) return;
      r.accepted = outcome === "accepted";
      r.rejected = outcome === "rejected";
    });
  }

  let justAddedId = null;   // frisch angelegte Zeile in der Verwaltung blendet weich ein
  function addPlayer(){
    const nid = uid("p"); justAddedId = nid;
    mutateState(s => {
      s.players.push({ id: nid, name: "Neue*r Spieler*in", role: "sub" });
    });
  }
  function updatePlayer(id, field, value){
    mutateState(s => {
      const p = s.players.find(p => p.id === id);
      if (!p) return;
      p[field] = value;
    });
  }
  function removePlayer(id){
    mutateState(s => {
      s.players = s.players.filter(p => p.id !== id);
      Object.keys(s.availability || {}).forEach(mdId => {
        if (s.availability[mdId]) delete s.availability[mdId][id];
      });
      (s.matchdays || []).forEach(md => {
        md.reschedule = (md.reschedule || []).filter(r => r.playerId !== id);
      });
    });
    if (getMe() === id) setMe("");
  }

  function addMatchday(pre){
    pre = pre && pre.date !== undefined ? pre : null;
    const overlay = document.getElementById("modalOverlay");
    const box = document.getElementById("modalBox");
    openModalTarget = { kind: "matchday-add" };
    box.className = "modal-box";
    const n = (state.matchdays || []).length + 1;
    box.innerHTML =
      '<div class="modal-head"><h3>Spieltag hinzufügen</h3><button class="modal-close" id="modalCloseBtn" type="button">' + ICO.x + '</button></div>' +
      '<div class="modal-section-title">Bezeichnung</div>' +
      '<input type="text" id="addLabel" value="' + escapeHtml("Spieltag " + n) + '" style="width:100%">' +
      '<div class="modal-section-title">Gegner</div>' +
      '<input type="text" id="addOpponent" placeholder="Gegner" style="width:100%">' +
      '<div class="modal-section-title">Termin</div>' +
      '<div class="modal-datetime-row"><input type="date" id="addDate"><input type="time" id="addTime"></div>' +
      '<div class="add-cal-hint" id="addCalHint" hidden></div>' +
      '<div class="add-suggest"><button class="btn small" type="button" id="addSuggest">' + L("Termine vorschlagen", "Suggest dates") + '</button><div class="sug-list" id="addSuggestList"></div></div>' +
      '<div class="modal-section-title">Prime-League-Link (optional)</div>' +
      '<input type="text" id="addPl" placeholder="https://www.primeleague.gg/…" style="width:100%">' +
      '<label class="modal-check" style="margin-top:14px"><input type="checkbox" id="addPing" checked> Discord-Ping senden</label>' +
      '<div class="modal-actions" style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px">' +
      '<button class="btn small" type="button" id="addCancel">Abbrechen</button>' +
      '<button class="btn small" type="button" id="addConfirm" disabled>Hinzufügen</button></div>';
    overlay.style.display = "flex";
    overlay.classList.remove("closing");
    const $ = id => document.getElementById(id);
    const check = () => { $("addConfirm").disabled = !($("addLabel").value.trim() && $("addOpponent").value.trim() && $("addDate").value && $("addTime").value); };
    ["addLabel", "addOpponent", "addDate", "addTime"].forEach(id => { $(id).addEventListener("input", check); $(id).addEventListener("change", check); });
    // Kalender-Hinweis: wer kann laut Kalender an diesem Termin (3 Stunden ab Anpfiff)?
    const pad2 = v => String(v).padStart(2, "0");
    const calCoreOf = () => { const act = activePlayers(), st = act.filter(p => p.role === "start"); return st.length ? st : act; };
    const freeFor = (ds, startMin) => {
      const core = calCoreOf(), free = [], busy = [];
      core.forEach(p => { let ok = true; for (let m = startMin; m < Math.min(startMin + CAL_MD_MIN, 1440); m += 15) if (!calAvailableAt(p, ds, m + 7)){ ok = false; break; } (ok ? free : busy).push(p); });
      return { core, free, busy };
    };
    const refreshHint = () => {
      const hint = $("addCalHint"), ds = $("addDate").value, tm = $("addTime").value;
      if (!ds || !tm){ hint.hidden = true; return; }
      const r = freeFor(ds, calMin(tm, false));
      hint.hidden = false;
      if (!r.core.length){ hint.hidden = true; return; }
      if (!r.busy.length){ hint.className = "add-cal-hint ok"; hint.textContent = L("Laut Kalender können alle (" + r.core.length + " von " + r.core.length + ").", "According to the calendar everyone can make it (" + r.core.length + " of " + r.core.length + ")."); }
      else { hint.className = "add-cal-hint warn"; hint.textContent = L("Laut Kalender nur " + r.free.length + " von " + r.core.length + " verfügbar – nicht verfügbar: " + r.busy.map(p => p.name).join(", ") + ".", "According to the calendar only " + r.free.length + " of " + r.core.length + " are available – unavailable: " + r.busy.map(p => p.name).join(", ") + "."); }
    };
    ["addDate", "addTime"].forEach(id => { $(id).addEventListener("input", refreshHint); $(id).addEventListener("change", refreshHint); });
    $("addSuggest").addEventListener("click", () => {
      const list = $("addSuggestList"), now = new Date(), todayIso = calIso(now), nowMin = now.getHours() * 60 + now.getMinutes();
      const out = [];
      for (let d = 0; d < 28; d++){
        const dt = new Date(now); dt.setDate(dt.getDate() + d); const ds = calIso(dt);
        for (let s = 10 * 60; s <= 21 * 60; s += 30){
          if (ds === todayIso && s <= nowMin) continue;
          const r = freeFor(ds, s); if (!r.core.length) continue;
          out.push({ ds, s, free: r.free.length, total: r.core.length, d });
        }
      }
      out.sort((x, y) => (y.free - x.free) || (x.d - y.d) || (Math.abs(x.s - 19 * 60) - Math.abs(y.s - 19 * 60)));
      const pick = [], perDay = {};
      out.forEach(o2 => { if (pick.length < 6 && (perDay[o2.ds] || 0) < 2){ pick.push(o2); perDay[o2.ds] = (perDay[o2.ds] || 0) + 1; } });
      pick.sort((x, y) => (y.free - x.free) || (x.d - y.d) || (x.s - y.s));
      list.innerHTML = "";
      if (!pick.length){ const e = document.createElement("div"); e.className = "add-cal-hint"; e.textContent = L("Keine passenden Termine in den nächsten 4 Wochen.", "No suitable dates in the next 4 weeks."); list.appendChild(e); return; }
      pick.forEach(o2 => {
        const b = document.createElement("button"); b.type = "button"; b.className = "sug-chip" + (o2.free === o2.total ? " all" : "");
        b.textContent = calDate(o2.ds).toLocaleDateString(UI.locale(), { weekday: "short", day: "2-digit", month: "2-digit" }) + " " + pad2(Math.floor(o2.s / 60)) + ":" + pad2(o2.s % 60) + " · " + o2.free + "/" + o2.total;
        b.addEventListener("click", () => { $("addDate").value = o2.ds; $("addTime").value = pad2(Math.floor(o2.s / 60)) + ":" + pad2(o2.s % 60); check(); refreshHint(); list.innerHTML = ""; });
        list.appendChild(b);
      });
    });
    if (pre){ $("addDate").value = pre.date || ""; $("addTime").value = pre.time || ""; check(); refreshHint(); }
    $("addCancel").addEventListener("click", closeModal);
    $("modalCloseBtn").addEventListener("click", closeModal);
    $("addConfirm").addEventListener("click", () => {
      check();
      if ($("addConfirm").disabled) return;
      const md = { id: uid("md"), label: $("addLabel").value.trim(), date: $("addDate").value, time: $("addTime").value, opponent: $("addOpponent").value.trim(), reschedule: [], createdAt: Date.now() };
      const pl = $("addPl").value.trim();
      if (pl) md.plLink = pl;
      const ping = $("addPing").checked;
      justAddedId = md.id;
      mutateState(s => { s.matchdays.push(md); });
      closeModal();
      if (ping) discordNotify("match", l => ({
        title: UI.Tl("Neues Match: ", l) + mdTitle(md),
        description: "**" + mdWhen(md, l) + "**" + (md.label ? "\n" + UI.Tl(md.label, l) : "")
      }));
    });
    setTimeout(() => { const f = document.getElementById("addOpponent"); if (f) f.focus(); }, 50);
  }
  function updateMatchday(id, field, value){
    mutateState(s => {
      const md = s.matchdays.find(m => m.id === id);
      if (!md) return;
      md[field] = value;
    });
  }
  function removeMatchday(id){
    mutateState(s => {
      s.matchdays = s.matchdays.filter(m => m.id !== id);
      delete s.availability[id];
    });
  }

  const ICON_USER = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="square" stroke-linejoin="miter" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7"/></svg>';
  let doLogout = () => { setMe(""); animateMe = true; render(); };
  function meLabel(me){
    if (me === ADMIN_ID) return adminName() + " (Admin)";
    const mp = me ? playerById(me) : null;
    if (mp) return mp.name || "—";
    return AUTH_CONFIG.discord ? (((authClaims && authClaims.dname) || "Discord") + " (nicht zugeordnet)") : L("Nicht angemeldet", "Not signed in");
  }
  function renderWhoAmI(){
    const me = getMe();
    const btn = document.getElementById("meBtn"), menu = document.getElementById("meMenu"), meEl = document.getElementById("meAvatar");
    const mp = me ? playerById(me) : null;
    meEl.innerHTML = mp ? avatarHtml(mp) : ICON_USER;
    btn.title = meLabel(me);
    let h = '<div class="me-menu-head"><strong>' + escapeHtml(meLabel(me)) + '</strong></div>';
    if (mp) h += '<a class="me-menu-item" href="#player/' + encodeURIComponent(me) + '" role="menuitem">' + L("Mein Profil", "My profile") + '</a>';
    if (AUTH_CONFIG.discord || me) h += '<button class="me-menu-item" type="button" data-me-logout role="menuitem">' + L("Abmelden", "Sign out") + '</button>';
    if (!AUTH_CONFIG.discord){
      h += '<div class="me-menu-title">' + (me ? L("Nutzer wechseln", "Switch user") : L("Anmelden als", "Sign in as")) + '</div><div class="me-menu-list">';
      activePlayers().forEach(p => { h += '<button class="me-menu-item' + (p.id === me ? " cur" : "") + '" type="button" data-me-pick="' + p.id + '" role="menuitem">' + avatarHtml(p) + '<span>' + escapeHtml(p.name || "—") + '</span></button>'; });
      h += '<button class="me-menu-item' + (me === ADMIN_ID ? " cur" : "") + '" type="button" data-me-pick="' + ADMIN_ID + '" role="menuitem">' + avatarHtml(playerById(ADMIN_ID)) + '<span>' + escapeHtml(adminName()) + ' (Admin)</span></button></div>';
    }
    menu.innerHTML = h;
    document.title = teamTag() + " Planer";
    const plA = document.getElementById("plTeamLink");
    if (plA){
      const pl = safeLink(plTeamLink());
      if (pl){ plA.href = pl; plA.style.display = ""; } else { plA.removeAttribute("href"); plA.style.display = "none"; }
    }
    const logoEl = document.getElementById("teamLogo");
    const logoA = document.getElementById("teamLogoLink");
    if (logoEl && logoA){
      if (state && state.teamLogo && /^data:image\//.test(state.teamLogo)){
        logoEl.src = state.teamLogo; logoA.style.display = "";
        const lk = safeLink(plTeamLink());
        if (lk){ logoA.href = lk; logoA.title = lk; } else { logoA.removeAttribute("href"); logoA.removeAttribute("title"); }
      } else { logoEl.removeAttribute("src"); logoA.style.display = "none"; }
    }
  }
  function setTeamField(field, value){
    mutateState(s => { s[field] = value; });
  }

  // ---------- Profilbilder (klein gespeichert: 96x96 WebP/JPEG als Data-URL im Spielerobjekt) ----------
  function avatarHtml(p){
    if (!p) return "";
    if (p.avatar && /^data:image\//.test(p.avatar)) return '<img class="avatar" src="' + p.avatar + '" alt="">';
    const ch = String(p.name || "?").trim().charAt(0).toUpperCase() || "?";
    return '<span class="avatar ph">' + escapeHtml(ch) + '</span>';
  }
  function resizeAvatarFile(file, size){
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(file);
      const img = new Image();
      img.onload = () => {
        try {
          size = size || 96;
          const side = Math.min(img.naturalWidth, img.naturalHeight);
          const sx = (img.naturalWidth - side) / 2, sy = (img.naturalHeight - side) / 2;
          const canvas = document.createElement("canvas");
          canvas.width = size; canvas.height = size;
          canvas.getContext("2d").drawImage(img, sx, sy, side, side, 0, 0, size, size);
          let out = canvas.toDataURL("image/webp", 0.8);
          if (out.indexOf("data:image/webp") !== 0) out = canvas.toDataURL("image/jpeg", 0.8);
          URL.revokeObjectURL(url);
          resolve(out);
        } catch(e){ URL.revokeObjectURL(url); reject(e); }
      };
      img.onerror = () => { URL.revokeObjectURL(url); reject(new Error("Bild konnte nicht gelesen werden")); };
      img.src = url;
    });
  }

  function renderRosterBar(){
    const bar = document.getElementById("rosterBar");
    bar.innerHTML = "";
    activePlayers().forEach(p => {
      const wrap = document.createElement("div");
      wrap.className = "chip-wrap";

      const chip = document.createElement("a");
      chip.href = "#player/" + encodeURIComponent(p.id);
      chip.className = "chip" + (p.role === "start" ? " start" : "");
      const lane = laneById(p.lane);
      const iconHtml = lane ? '<img class="role-icon" src="' + lane.icon + '" alt="' + lane.label + '" title="' + lane.label + '">' : '';
      chip.innerHTML = iconHtml + '<strong>' + escapeHtml(p.name || "—") + '</strong>';
      wrap.appendChild(chip);

      bar.appendChild(wrap);
    });
    if (!activePlayers().length){
      bar.innerHTML = '<span class="chip">Noch keine Spieler:innen &ndash; über „Verwaltung" hinzufügen</span>';
    }
  }

  function escapeHtml(str){
    return String(str || "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  }

  // ---------- Backup: Export / Import aller Teamdaten als JSON-Datei ----------
  function renderBackupCard(){
    const box = document.getElementById("manageBackup");
    if (!box) return;
    box.innerHTML = '<h3>Backup</h3>' +
      '<p class="manage-hint">Alle Teamdaten als Datei sichern oder eine Sicherung wieder einspielen. Der Discord-Webhook ist nicht enthalten.</p>' +
      '<div class="manage-item"><button class="btn small" type="button" id="bkExport">Daten exportieren</button>' +
      '<label class="btn small" for="bkImport">Daten importieren</label><input type="file" id="bkImport" accept="application/json,.json" hidden></div>';
    document.getElementById("bkExport").addEventListener("click", () => {
      const data = cloneState(state);
      delete data.discordWebhook; delete data.discordTestWebhook;
      const blob = new Blob([JSON.stringify({ app: "unc-planer", version: 1, exported: new Date().toISOString(), data: data }, null, 1)], { type: "application/json" });
      const a = document.createElement("a");
      a.href = URL.createObjectURL(blob);
      a.download = teamTag().toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-planer-backup-" + new Date().toISOString().slice(0, 10) + ".json";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 2000);
    });
    document.getElementById("bkImport").addEventListener("change", async (e) => {
      const f = e.target.files && e.target.files[0];
      e.target.value = "";
      if (!f) return;
      let parsed;
      try { parsed = JSON.parse(await f.text()); } catch(err){ parsed = null; }
      const data = parsed && parsed.app === "unc-planer" ? parsed.data : null;
      if (!data || !Array.isArray(data.players) || !Array.isArray(data.matchdays)){
        uiAlert("Das ist keine gültige Sicherungsdatei des " + teamTag() + " Planers.");
        return;
      }
      uiConfirm("Alle aktuellen Daten werden durch die Sicherung ersetzt (" + data.players.length + " Spieler:innen, " + data.matchdays.length + " Spieltage). Fortfahren?", { danger: true }).then(okk => {
        if (!okk) return;
        mutateState(s => {
          const keep = { discordWebhook: s.discordWebhook, discordTestWebhook: s.discordTestWebhook };
          Object.keys(s).forEach(k => delete s[k]);
          Object.assign(s, data);
          if (keep.discordWebhook) s.discordWebhook = keep.discordWebhook;
          if (keep.discordTestWebhook) s.discordTestWebhook = keep.discordTestWebhook;
        });
      });
    });
  }

  // Discord-Karte in der Verwaltung. Alter Modus: Werte im Team-Dokument. Discord-Modus: Werte liegen nur auf dem Server (nur Admin).
  const DC_LEGACY = { webhook: "discordWebhook", role: "discordRole", testWebhook: "discordTestWebhook", testRole: "discordTestRole", testMode: "discordTestMode" };
  function dcSave(key, val){
    if (!AUTH_CONFIG.discord) return setTeamField(DC_LEGACY[key], val);
    const body = {}; body[key] = val;
    callApi("/config", "POST", body).then(r => {
      if (r){ dcServer.cfg = r; if (!!state.discordOn !== !!r.on) setTeamField("discordOn", !!r.on); }
      renderManage();
    });
  }
  function renderDiscordCard(dcBox){
    let v;
    if (AUTH_CONFIG.discord){
      if (!isAdmin()){
        dcBox.innerHTML = '<h3>Discord</h3><p class="manage-hint">Die Discord-Einstellungen sehen und ändern nur Admins.</p>' +
          '<div class="manage-item"><div class="manage-linkrow"><strong>Sprache der Nachrichten</strong><select id="dcLang"><option value="de"' + (discordLang() === "de" ? " selected" : "") + '>Deutsch</option><option value="en"' + (discordLang() === "en" ? " selected" : "") + '>English</option></select></div></div>';
        document.getElementById("dcLang").addEventListener("change", e => setTeamField("discordLang", e.target.value));
        return;
      }
      if (!dcServer.cfg){
        dcBox.innerHTML = '<h3>Discord</h3><p class="manage-hint">Lade Einstellungen …</p>';
        if (!dcServer.loading){
          dcServer.loading = true;
          callApi("/config", "GET").then(r => { dcServer.loading = false; dcServer.cfg = r || { webhook: "", role: "", testWebhook: "", testRole: "", testMode: false, on: false, failed: true }; renderManage(); });
        }
        return;
      }
      v = { test: dcServer.cfg.testMode, webhook: dcServer.cfg.webhook, role: dcServer.cfg.role, testWebhook: dcServer.cfg.testWebhook, testRole: dcServer.cfg.testRole };
    } else {
      v = { test: !!state.discordTestMode, webhook: state.discordWebhook, role: state.discordRole, testWebhook: state.discordTestWebhook, testRole: state.discordTestRole };
    }
    dcBox.innerHTML =
        '<h3>Discord</h3>' +
        '<p class="manage-hint">Benachrichtigungen im Team-Kanal über einen Webhook.</p>' +
        '<label class="modal-check"><input type="checkbox" id="dcTestMode"' + (v.test ? " checked" : "") + '> Testmodus: Nachrichten gehen an den Test-Discord</label>' +
        (v.test ? '<p class="manage-hint" style="color:var(--accent)">Testmodus ist AN – der Team-Kanal bekommt gerade nichts.</p>' : '') +
        '<div class="manage-item"><div class="manage-linkrow"><strong>Webhook</strong><input type="text" id="dcWebhook" class="opgg-input" placeholder="https://discord.com/api/webhooks/…" value="' + escapeHtml(v.webhook || "") + '"></div></div>' +
        '<div class="manage-item"><div class="manage-linkrow"><strong>Rollen-ID @team</strong><input type="text" id="dcRole" class="opgg-input" placeholder="Rollen-ID (leer = nur Text @team ohne Ping)" value="' + escapeHtml(v.role || "") + '"></div></div>' +
        '<div class="manage-item"><div class="manage-linkrow"><strong>Test-Webhook</strong><input type="text" id="dcTestWebhook" class="opgg-input" placeholder="https://discord.com/api/webhooks/… (Test-Server)" value="' + escapeHtml(v.testWebhook || "") + '"></div></div>' +
        '<div class="manage-item"><div class="manage-linkrow"><strong>Test-Rollen-ID</strong><input type="text" id="dcTestRole" class="opgg-input" placeholder="Rollen-ID auf dem Test-Server" value="' + escapeHtml(v.testRole || "") + '"></div></div>' +
        '<div class="manage-item"><div class="manage-linkrow"><strong>Sprache der Nachrichten</strong><select id="dcLang"><option value="de"' + (discordLang() === "de" ? " selected" : "") + '>Deutsch</option><option value="en"' + (discordLang() === "en" ? " selected" : "") + '>English</option></select></div></div>' +
        '<div class="manage-item"><button class="btn small" type="button" id="dcTest">Test senden</button></div>';
      document.getElementById("dcLang").addEventListener("change", e => setTeamField("discordLang", e.target.value));
      const dcW = document.getElementById("dcWebhook"), dcR = document.getElementById("dcRole");
      dcW.addEventListener("change", () => dcSave("webhook", dcW.value.trim()));
      dcR.addEventListener("change", () => dcSave("role", dcR.value.trim()));
      document.getElementById("dcTestWebhook").addEventListener("change", e => dcSave("testWebhook", e.target.value.trim()));
      document.getElementById("dcTestRole").addEventListener("change", e => dcSave("testRole", e.target.value.trim()));
      document.getElementById("dcTestMode").addEventListener("change", e => dcSave("testMode", e.target.checked));
      document.getElementById("dcTest").addEventListener("click", async (e) => {
        const btn = e.currentTarget;
        btn.textContent = "Sende …";
        const ok = await discordSend(l => ({ title: "Test", description: UI.Tl("Die Verbindung zum " + teamTag() + " Planer funktioniert.", l) }));
        btn.textContent = ok ? "Gesendet" : "Fehlgeschlagen";
        setTimeout(() => { btn.textContent = "Test senden"; }, 2500);
      });
    const legacyHook = AUTH_CONFIG.discord && isAdmin() && state.discordWebhook;
    if (legacyHook){
      const mig = document.createElement("div");
      mig.className = "manage-item";
      mig.innerHTML = '<button class="btn small" type="button" id="dcMigrate">Alten Webhook aus der Datenbank übernehmen</button>';
      dcBox.appendChild(mig);
      document.getElementById("dcMigrate").addEventListener("click", async () => {
        const r = await callApi("/config", "POST", { webhook: state.discordWebhook, role: String(state.discordRole || ""), testWebhook: String(state.discordTestWebhook || ""), testRole: String(state.discordTestRole || "") });
        if (!r){ uiAlert("Das hat nicht geklappt. Läuft die Cloud Function?"); return; }
        dcServer.cfg = r;
        mutateState(s => { ["discordWebhook", "discordRole", "discordTestWebhook", "discordTestRole", "discordTestMode"].forEach(k => delete s[k]); s.discordOn = !!r.on; });
      });
    }
  }

