  function openCalProposalModal(ds, time){
    const mds = calOpenMatchdays(); if (!mds.length) return;
    if (!getMe()){ uiAlert(needMeMsg()); return; }
    const today = calIso(new Date());
    const def = (calSel && mds.find(m => m.id === calSel)) || mds.find(m => m.date && m.date >= today) || mds[0];
    const overlay = document.getElementById("modalOverlay"), box = document.getElementById("modalBox");
    openModalTarget = { kind: "cal-proposal" };
    box.className = "modal-box";
    box.innerHTML = '<div class="modal-head"><h3>' + L("Terminvorschlag hinzufügen", "Add date proposal") + '</h3><button class="modal-close" id="modalCloseBtn" type="button">' + ICO.x + '</button></div>' +
      '<div class="modal-section-title">' + L("Spieltag", "Matchday") + '</div><select id="cpMd" style="width:100%">' + mds.map(m => '<option value="' + m.id + '"' + (m.id === def.id ? " selected" : "") + '>' + escapeHtml((m.label || "") + " · vs " + (m.opponent || "?") + (m.date ? " · " + calDate(m.date).toLocaleDateString(UI.locale(), { day: "2-digit", month: "2-digit" }) : "")) + '</option>').join("") + '</select>' +
      '<div class="modal-section-title">' + L("Datum", "Date") + '</div><input type="date" id="cpDate" style="width:100%">' +
      '<div class="modal-section-title">' + L("Uhrzeit (optional, leer = nur für den Tag)", "Time (optional, empty = day only)") + '</div><input type="time" id="cpTime" style="width:100%">' +
      '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px"><button class="btn small" type="button" id="cpCancel">' + L("Abbrechen", "Cancel") + '</button><button class="btn small" type="button" id="cpSave">' + L("Vorschlagen", "Propose") + '</button></div>';
    overlay.style.display = "flex"; overlay.classList.remove("closing");
    const $ = id => document.getElementById(id);
    $("cpDate").value = ds; $("cpTime").value = time || "";
    const check = () => { $("cpSave").disabled = !$("cpDate").value; };
    $("cpDate").addEventListener("input", check); check();
    $("cpCancel").addEventListener("click", closeModal); $("modalCloseBtn").addEventListener("click", closeModal);
    $("cpSave").addEventListener("click", () => {
      check(); if ($("cpSave").disabled) return;
      addReschedule($("cpMd").value, formatDateAsProposal($("cpDate").value, $("cpTime").value));
      closeModal();
    });
  }


  function openCalEntryModal(pid, itemId, pre){
    const p = (state.players || []).find(x => x.id === pid);
    if (!p) return;
    const ex = itemId ? calOf(p).items.find(i => i.id === itemId) : null;
    const it = ex ? JSON.parse(JSON.stringify(ex)) : { kind: "once", type: "block", days: [], allDay: false, from: "18:00", to: "00:00", start: "", end: "", startTime: "", endTime: "", note: "", paused: false, pausedUntil: "" };
    if (!ex && pre){
      it.kind = "once"; it.start = pre.date || ""; if (pre.type) it.type = pre.type;
      if (pre.time){ const hh = parseInt(pre.time, 10); it.from = pre.time; it.to = String((hh + 1) % 24).padStart(2, "0") + ":" + pre.time.slice(3, 5); }
    }
    openModalTarget = { kind: "cal-entry" };
    const overlay = document.getElementById("modalOverlay"), box = document.getElementById("modalBox");
    box.className = "modal-box";
    const sec = t => '<div class="modal-section-title">' + t + '</div>';
    box.innerHTML =
      '<div class="modal-head"><h3>' + (ex ? L("Eintrag bearbeiten", "Edit entry") : L("Eintrag hinzufügen", "Add entry")) + '</h3><button class="modal-close" id="modalCloseBtn" type="button">' + ICO.x + '</button></div>' +
      '<div class="modal-sub">' + escapeHtml(p.name || "") + '</div>' +
      sec(L("Art", "Type")) + '<select id="ceType" style="width:100%"><option value="block">' + L("Nicht verfügbar", "Unavailable") + '</option><option value="free">' + L("Verfügbar", "Available") + '</option></select>' +
      sec(L("Wiederholung", "Repeat")) + '<select id="ceKind" style="width:100%"><option value="once">' + L("Einmalig (Datum und Uhrzeit)", "Once (date and time)") + '</option><option value="range">' + L("Zeitraum (von – bis, mehrere Tage)", "Date range (from – to, several days)") + '</option><option value="weekly">' + L("Wöchentlich", "Weekly") + '</option></select>' +
      '<div id="ceOnce">' + sec(L("Datum", "Date")) + '<input type="date" id="ceStart" style="width:100%"></div>' +
      '<div id="ceRange">' + sec(L("Von (Datum, Uhrzeit optional)", "From (date, time optional)")) + '<div class="modal-datetime-row"><input type="date" id="ceRStart"><input type="time" id="ceRStartT"></div>' +
        sec(L("Bis (Datum, Uhrzeit optional)", "Until (date, time optional)")) + '<div class="modal-datetime-row"><input type="date" id="ceREnd"><input type="time" id="ceREndT"></div>' +
        '<p class="manage-hint">' + L("Ohne Uhrzeit beim Starttag zählt der ganze Starttag, ohne Uhrzeit beim Endtag der ganze Endtag.", "Without a time on the first day the whole first day counts, without a time on the last day the whole last day counts.") + '</p></div>' +
      '<div id="ceWeekly">' + sec(L("Wochentage", "Weekdays")) + '<div class="cal-days">' + [0, 1, 2, 3, 4, 5, 6].map(i => '<button type="button" class="toggle-chip" data-ce-day="' + i + '">' + calWdName(i) + '</button>').join("") + '</div></div>' +
      '<div id="ceTimeBlock"><label class="modal-check" style="margin-top:12px"><input type="checkbox" id="ceAll"> ' + L("Ganztägig", "All day") + '</label>' +
      '<div id="ceTimes">' + sec(L("Uhrzeit von – bis", "Time from – to")) + '<div class="modal-datetime-row"><input type="time" id="ceFrom"><input type="time" id="ceTo"></div></div></div>' +
      sec(L("Notiz (optional)", "Note (optional)")) + '<input type="text" id="ceNote" style="width:100%">' +
      '<div id="cePause"><label class="modal-check" style="margin-top:12px"><input type="checkbox" id="cePaused"> ' + L("Pausiert", "Paused") + '</label>' +
      '<div id="cePauseUntil">' + sec(L("Pausiert bis (leer = unbegrenzt)", "Paused until (empty = indefinitely)")) + '<input type="date" id="cePUntil"></div></div>' +
      '<div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px"><button class="btn small" type="button" id="ceCancel">' + L("Abbrechen", "Cancel") + '</button><button class="btn small" type="button" id="ceSave" disabled>' + L("Speichern", "Save") + '</button></div>';
    overlay.style.display = "flex"; overlay.classList.remove("closing");
    const $ = id => document.getElementById(id);
    const legacyRange = it.kind === "once" && it.end && it.end !== it.start;
    $("ceType").value = it.type; $("ceKind").value = it.kind;
    $("ceStart").value = it.kind === "once" ? (it.start || "") : ""; $("ceRStart").value = it.kind === "range" ? (it.start || "") : ""; $("ceREnd").value = it.kind === "range" ? (it.end || "") : "";
    $("ceRStartT").value = it.startTime || ""; $("ceREndT").value = it.endTime || "";
    $("ceAll").checked = !!it.allDay; $("ceFrom").value = it.from || ""; $("ceTo").value = it.to || ""; $("ceNote").value = it.note || "";
    $("cePaused").checked = !!it.paused; $("cePUntil").value = it.pausedUntil || "";
    const days = new Set(it.days || []);
    const refresh = () => {
      const kind = $("ceKind").value, all = $("ceAll").checked;
      $("ceOnce").style.display = kind === "once" ? "" : "none"; $("ceRange").style.display = kind === "range" ? "" : "none"; $("ceWeekly").style.display = kind === "weekly" ? "" : "none";
      $("ceTimeBlock").style.display = kind === "range" ? "none" : ""; $("ceTimes").style.display = all ? "none" : "";
      $("cePause").style.display = kind === "weekly" ? "" : "none"; $("cePauseUntil").style.display = $("cePaused").checked ? "" : "none";
      box.querySelectorAll("[data-ce-day]").forEach(b => b.classList.toggle("on", days.has(+b.dataset.ceDay)));
      const timesOk = all || ($("ceFrom").value && $("ceTo").value);
      let ok;
      if (kind === "weekly") ok = days.size > 0 && timesOk;
      else if (kind === "range") ok = !!$("ceRStart").value && !!$("ceREnd").value && $("ceREnd").value >= $("ceRStart").value;
      else ok = !!$("ceStart").value && timesOk;
      $("ceSave").disabled = !ok;
    };
    box.querySelectorAll("[data-ce-day]").forEach(b => b.addEventListener("click", () => { const d = +b.dataset.ceDay; days.has(d) ? days.delete(d) : days.add(d); refresh(); }));
    ["ceType", "ceKind", "ceStart", "ceRStart", "ceREnd", "ceRStartT", "ceREndT", "ceAll", "ceFrom", "ceTo", "cePaused", "cePUntil"].forEach(id => { $(id).addEventListener("change", refresh); $(id).addEventListener("input", refresh); });
    $("ceCancel").addEventListener("click", closeModal); $("modalCloseBtn").addEventListener("click", closeModal);
    $("ceSave").addEventListener("click", () => {
      refresh(); if ($("ceSave").disabled) return;
      const kind = $("ceKind").value;
      const n = { id: ex ? ex.id : uid("cal"), kind: kind, type: $("ceType").value, note: $("ceNote").value.trim() };
      if (kind === "range"){
        n.start = $("ceRStart").value; n.end = $("ceREnd").value;
        if ($("ceRStartT").value) n.startTime = $("ceRStartT").value;
        if ($("ceREndT").value) n.endTime = $("ceREndT").value;
      } else {
        n.allDay = $("ceAll").checked;
        if (!n.allDay){ n.from = $("ceFrom").value; n.to = $("ceTo").value; }
        if (kind === "weekly"){ n.days = [...days].sort(); n.paused = $("cePaused").checked; n.pausedUntil = n.paused ? $("cePUntil").value : ""; }
        else { n.start = $("ceStart").value; n.end = legacyRange && ex ? ex.end : n.start; }
      }
      calEdit(pid, cal => { const ix = cal.items.findIndex(x => x.id === n.id); if (ix >= 0) cal.items[ix] = n; else cal.items.push(n); });
      closeModal();
    });
    refresh();
  }

  function entryNoStatus(e){ return !e || !e.status; }
  function renderGrid(){
    const grid = document.getElementById("grid");
    const gridCompleted = document.getElementById("gridCompleted");
    const completedHeading = document.getElementById("completedHeading");
    grid.innerHTML = "";
    gridCompleted.innerHTML = "";
    const me = getMe();

    if (!(state.matchdays || []).length){
      grid.innerHTML = '<div class="visually-empty">Noch keine Spieltage angelegt. Über „Verwaltung" hinzufügen.</div>';
      gridCompleted.style.display = "none";
      completedHeading.style.display = "none";
      return;
    }

    const byDateAsc = (a, b) => {
      if (a.date && b.date) return a.date.localeCompare(b.date);
      if (a.date) return -1;
      if (b.date) return 1;
      return 0;
    };

    const open = state.matchdays.filter(md => !md.result).sort(byDateAsc);
    const completed = state.matchdays.filter(md => md.result).sort((a, b) => byDateAsc(b, a)); // neueste zuerst

    // "Aktueller" Spieltag = offener Spieltag mit dem nähesten Datum ab heute (ohne Datum zählt nicht mit)
    const now = new Date();
    const todayStr = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
    const upcoming = open.filter(md => md.date && md.date >= todayStr).sort(byDateAsc);
    const currentId = upcoming.length ? upcoming[0].id : null;

    if (!open.length){
      grid.innerHTML = '<div class="visually-empty">Keine offenen Spieltage mehr.</div>';
    } else {
      open.forEach(md => grid.appendChild(buildMatchdayCard(md, me, md.id === currentId)));
    }

    if (completed.length){
      completedHeading.style.display = "";
      gridCompleted.style.display = "";
      completed.forEach(md => gridCompleted.appendChild(buildMatchdayCard(md, me, false)));
    } else {
      completedHeading.style.display = "none";
      gridCompleted.style.display = "none";
    }

    applyCollapse();
    const wrap = document.getElementById("viewMain");
    wrap.querySelectorAll(".tbtn").forEach(btn => {
      btn.addEventListener("click", () => setAvailability(btn.dataset.md, btn.dataset.p, btn.dataset.status));
    });
    wrap.querySelectorAll(".vote-slot.editable > .vote-badge").forEach(badge => {
      badge.addEventListener("click", () => badge.closest(".vote-slot").classList.toggle("expanded"));
    });
    wrap.querySelectorAll("[data-edit-note]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const key = btn.dataset.editNote + ":" + btn.dataset.notePlayer;
        const editRow = wrap.querySelector('[data-note-edit-row="' + key + '"]');
        if (!editRow) return;
        const input = editRow.querySelector(".note-input");
        if (!input) return;
        const open = editRow.style.display !== "none";
        if (open){
          input.blur();
          return;
        }
        editRow.style.display = "block";
        slideAnim(editRow, true);
        input.focus();
        input.select();
      });
    });
    wrap.querySelectorAll(".note-input").forEach(input => {
      const editRow = input.closest(".note-edit-row");
      const parts = (editRow?.dataset.noteEditRow || "").split(":");
      const mdId = parts.shift();
      const playerId = parts.join(":");
      const original = input.value;
      let saved = false;
      const save = () => {
        if (saved) return;
        saved = true;
        if (input.value !== original) setNote(mdId, playerId, input.value.trim());
        else slideAnim(editRow, false, () => { editRow.style.display = "none"; });
      };
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter"){
          e.preventDefault();
          input.blur();
        } else if (e.key === "Escape"){
          e.preventDefault();
          saved = true;
          input.value = original;
          slideAnim(editRow, false, () => { editRow.style.display = "none"; });
        }
      });
      input.addEventListener("blur", save);
    });
    wrap.querySelectorAll(".player-note").forEach(note => {
      note.addEventListener("click", (e) => {
        e.stopPropagation();
        openPlayerNotePopup(note);
      });
    });
    wrap.querySelectorAll("[data-ping]").forEach(btn => {
      btn.addEventListener("click", (e) => { e.stopPropagation(); sendProposalPing(btn.dataset.ping); });
    });
    wrap.querySelectorAll("[data-ask]").forEach(btn => {
      btn.addEventListener("click", () => {
        const input = wrap.querySelector('[data-reason="' + btn.dataset.ask + '"]');
        const d = input ? parseProposalDate(input.value) : null;
        if (!d){ if (input){ input.classList.add("invalid"); input.classList.remove("shake"); void input.offsetWidth; input.classList.add("shake"); input.focus(); } return; }
        const pad = n => String(n).padStart(2, "0");
        addReschedule(btn.dataset.ask, pad(d.day) + "." + pad(d.month) + "." + (d.hasTime ? " " + pad(d.hour) + ":" + pad(d.min) : ""));
        if (input){ input.value = ""; input.classList.remove("invalid"); }
      });
    });
    wrap.querySelectorAll("[data-reason]").forEach(inp => {
      inp.addEventListener("input", () => inp.classList.toggle("invalid", !!inp.value.trim() && !parseProposalDate(inp.value)));
      inp.addEventListener("keydown", e => { if (e.key === "Enter"){ e.preventDefault(); const b = wrap.querySelector('[data-ask="' + inp.dataset.reason + '"]'); if (b) b.click(); } });
    });
    wrap.querySelectorAll("[data-remove-req]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const rq = btn.closest(".req"), md0 = btn.dataset.md, id0 = btn.dataset.removeReq;
        if (rq) slideAnim(rq, false, () => removeReschedule(md0, id0)); else removeReschedule(md0, id0);
      });
    });
    wrap.querySelectorAll("[data-direct-vote]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        voteOnReschedule(btn.dataset.mdVote, btn.dataset.directVote, getMe(), btn.dataset.voteVal);
      });
    });
    wrap.querySelectorAll("[data-swap]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        uiConfirm("Diesen Termin als offiziellen Spieltag-Termin übernehmen? Der bisherige Termin wird dafür zu einem neuen Terminvorschlag.", { ok: L("Übernehmen", "Apply") }).then(o => {
          if (o) swapMatchdayDate(btn.dataset.mdSwap, btn.dataset.swap);
        });
      });
    });
    wrap.querySelectorAll("[data-toggle-resched]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const id = btn.dataset.toggleResched;
        const doToggle = () => {
          setReschedExpanded(id, !isReschedExpanded(id));
          if (isReschedExpanded(id)) animateReschedId = id;
          render();
        };
        if (isReschedExpanded(id)){
          const list = document.querySelector('[data-resched-list="' + id + '"]');
          slideAnim(list, false, doToggle);
        } else doToggle();
      });
    });
    wrap.querySelectorAll("[data-expand-completed]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const cid = btn.dataset.expandCompleted;
        expandedCompleted.add(cid);
        animateCardId = cid;
        render();
      });
    });
    wrap.querySelectorAll("[data-collapse-completed]").forEach(btn => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const cid = btn.dataset.collapseCompleted;
        const cardEl = btn.closest(".card");
        const doIt = () => { expandedCompleted.delete(cid); animateCardId = cid; render(); };
        fadeOut(cardEl ? [].slice.call(cardEl.children).slice(2) : [], doIt);
      });
    });
    wrap.querySelectorAll("[data-edit-md]").forEach(btn => {
      btn.addEventListener("click", () => openMatchdayEditModal(btn.dataset.editMd));
    });
    wrap.querySelectorAll("[data-open-proposal]").forEach(el => {
      el.addEventListener("click", () => {
        openRescheduleModal(el.dataset.mdProposal, el.dataset.openProposal);
      });
    });
    wrap.querySelectorAll("[data-save-result]").forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.saveResult;
        const usSel = wrap.querySelector('[data-res-us="' + id + '"]');
        const themSel = wrap.querySelector('[data-res-them="' + id + '"]');
        const us = parseInt(usSel.value, 10);
        const them = parseInt(themSel.value, 10);
        const mdObj = (state.matchdays || []).find(m => m.id === id);
        const scrim = !!mdObj && /scrim/i.test(mdObj.label || "");
        const valid = (us === 2 && them < 2) || (them === 2 && us < 2) || (scrim && us === 1 && them === 1);
        if (!valid){
          uiAlert("Kein gültiges Bo3-Ergebnis. Ein Team muss 2 Siege haben, das andere 0 oder 1 (z. B. 2:1 oder 0:2; bei Scrims zusätzlich 1:1).");
          return;
        }
        setResult(id, us, them);
      });
    });
    wrap.querySelectorAll("[data-edit-result]").forEach(btn => {
      btn.addEventListener("click", () => {
        editingResults.add(btn.dataset.editResult);
        render();
      });
    });
    wrap.querySelectorAll("[data-delete-result]").forEach(btn => {
      btn.addEventListener("click", () => {
        uiConfirm("Ergebnis wirklich löschen?", { danger: true, ok: L("Löschen", "Delete") }).then(o => { if (o) clearResult(btn.dataset.deleteResult); });
      });
    });
  }

  // ---- Ziele / To-dos pro Spieler:in (p.todos = [{ id, text, done }]); bearbeiten: die Person selbst und der Admin ----
  let todoDraft = "";
  function todoSectionHtml(p, canEdit){
    const todos = Array.isArray(p.todos) ? p.todos : [];
    const open = todos.filter(t => !t.done), done = todos.filter(t => t.done);
    const row = t => '<div class="todo-row' + (t.done ? " done" : "") + '"><label class="modal-check"><input type="checkbox" data-todo-toggle="' + t.id + '"' + (t.done ? " checked" : "") + (canEdit ? "" : " disabled") + '> <span class="todo-text">' + escapeHtml(t.text) + '</span></label>' +
      (canEdit ? '<button class="btn small danger" type="button" data-todo-del="' + t.id + '" title="' + L("Entfernen", "Remove") + '">' + ICO.x + '</button>' : '') + '</div>';
    return '<section class="todo-card"><h3>' + L("Ziele & To-dos", "Goals & to-dos") + (todos.length ? ' <span class="todo-count">' + done.length + "/" + todos.length + '</span>' : '') + '</h3>' +
      (todos.length ? '<div class="todo-list">' + open.map(row).join("") + done.map(row).join("") + '</div>' : '<p class="manage-hint">' + L("Noch keine Ziele eingetragen.", "No goals yet.") + '</p>') +
      (canEdit ? '<div class="todo-add"><input type="text" id="todoInput" maxlength="160" placeholder="' + L("Neues Ziel oder To-do …", "New goal or to-do …") + '" value="' + escapeHtml(todoDraft) + '"><button class="btn small" type="button" id="todoAddBtn">' + ICO.plus + " " + L("Hinzufügen", "Add") + '</button></div>' : '') + '</section>';
  }
  function wireTodos(container, p){
    const edit = fn => mutateState(s => { const q = s.players.find(x => x.id === p.id); if (q){ q.todos = Array.isArray(q.todos) ? q.todos : []; fn(q.todos); } });
    container.querySelectorAll("[data-todo-toggle]").forEach(cb => cb.addEventListener("change", () => edit(list => { const t = list.find(x => x.id === cb.dataset.todoToggle); if (t) t.done = cb.checked; })));
    container.querySelectorAll("[data-todo-del]").forEach(b => b.addEventListener("click", () => edit(list => { const i = list.findIndex(x => x.id === b.dataset.todoDel); if (i >= 0) list.splice(i, 1); })));
    const inp = document.getElementById("todoInput"), btn = document.getElementById("todoAddBtn");
    if (!inp || !btn) return;
    const add = () => { const v = inp.value.trim(); if (!v) return; todoDraft = ""; edit(list => { list.push({ id: uid("todo"), text: v, done: false }); }); };
    inp.addEventListener("input", () => { todoDraft = inp.value; });
    inp.addEventListener("keydown", e => { if (e.key === "Enter"){ e.preventDefault(); add(); } });
    btn.addEventListener("click", add);
  }
  function renderPlayerView(playerId){
    const container = document.getElementById("viewPlayer");
    const p = playerById(playerId);
    const navLinks = '<div class="nav-links">'
      + '<a href="#" class="back-link">' + ICO.left + ' Hauptseite</a>'
      + '<a href="#champions" class="back-link">Spielerübersicht ' + ICO.right + '</a>'
      + '</div>';
    if (!p){
      container.innerHTML = navLinks + '<p>Spieler:in nicht gefunden.</p>';
      const links = container.querySelectorAll(".back-link");
      links[0].addEventListener("click", (e) => { e.preventDefault(); location.hash = ""; });
      links[1].addEventListener("click", (e) => { e.preventDefault(); location.hash = "champions"; });
      return;
    }
    const me = getMe();
    const isMine = me === playerId;
    const lane = laneById(p.lane);

    let html = navLinks;

    html += '<div class="player-nav">';
    activePlayers().forEach(pl => {
      const plLane = laneById(pl.lane);
      const icon = plLane ? '<img class="role-icon" src="' + plLane.icon + '" alt="">' : '';
      html += '<a href="#player/' + encodeURIComponent(pl.id) + '" class="' + (pl.id === playerId ? "current" : "") + '">' + icon + escapeHtml(pl.name) + '</a>';
    });
    html += '</div>';

    html += '<div class="player-head">';
    if (lane) html += '<img class="role-icon" src="' + lane.icon + '" alt="' + lane.label + '">';
    html += '<h2>' + escapeHtml(p.name) + '</h2>';
    if (playerId !== ADMIN_ID) html += '<span class="tag">' + (p.role === "start" ? "main" : "sub") + '</span>';
    else html += '<span class="tag">Admin</span>';
    if (safeHref(p.opgg)){
      html += '<a href="' + escapeHtml(safeHref(p.opgg)) + '" target="_blank" rel="noopener noreferrer" class="opgg-link" title="OP.GG-Profil von ' + escapeHtml(p.name) + '"><img src="' + ICON_OPGG + '" alt="OP.GG"></a>';
    }
    html += '</div>';

    if (isMine) html += profileCardHtml(p, playerId === ADMIN_ID);
    if (playerId === ADMIN_ID){
      container.innerHTML = html;
      const na = container.querySelectorAll(".back-link");
      na[0].addEventListener("click", (e) => { e.preventDefault(); location.hash = ""; });
      na[1].addEventListener("click", (e) => { e.preventDefault(); location.hash = "champions"; });
      wireProfileCard(container, p, true);
      return;
    }
    html += todoSectionHtml(p, me === playerId || isAdmin());

    const tierOpen = !isCollapsed("tier");
    html += '<section class="todo-card tier-card"><h3 class="tier-card-head"><button type="button" class="sect-toggle" id="tierToggle" aria-expanded="' + (tierOpen ? "true" : "false") + '" title="' + (tierOpen ? "Einklappen" : "Ausklappen") + '"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="square" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></button><span>Tierlist</span></h3>';
    html += '<div class="collapsible' + (tierOpen ? " settled" : " collapsed") + '" id="tierCollapse"><div class="ci">';
    html += '<div class="tierlist" id="tierlistWrap">';
    TIERS.forEach(t => {
      html += '<div class="tier-row" data-tier-row="' + t + '">';
      html += '<div class="tier-label ' + t.toLowerCase() + '">' + t + '</div>';
      html += '<div class="tier-champs" data-tier-drop="' + t + '"><span class="champ-loading">Lädt…</span></div>';
      html += '</div>';
    });
    html += '</div>';

    if (isMine){
      html += '<button class="btn small champ-pool-toggle" id="champPoolToggle" type="button">' + (champPoolOpen ? "Champion-Auswahl schließen" : ICO.plus + " Champion importieren") + '</button>';
      html += '<div class="champ-pool" id="champPool" style="display:' + (champPoolOpen ? "block" : "none") + '">';
      html += '<input type="text" class="champ-pool-search" id="champSearch" placeholder="Champion suchen …" value="' + escapeHtml(champSearchText) + '">';
      html += '<div class="champ-grid" id="champGrid"><span class="champ-loading">Lade Champions von Data Dragon…</span></div>';
      html += '</div>';
    }
    html += '</div></div></section>';

    container.innerHTML = html;

    const navA = container.querySelectorAll(".back-link");
    navA[0].addEventListener("click", (e) => { e.preventDefault(); location.hash = ""; });
    navA[1].addEventListener("click", (e) => { e.preventDefault(); location.hash = "champions"; });

    if (isMine){
      const toggleBtn = document.getElementById("champPoolToggle");
      toggleBtn.addEventListener("click", () => {
        champPoolOpen = !champPoolOpen;
        document.getElementById("champPool").style.display = champPoolOpen ? "block" : "none";
        toggleBtn.innerHTML = champPoolOpen ? "Champion-Auswahl schließen" : ICO.plus + " Champion importieren";
      });
      const searchInput = document.getElementById("champSearch");
      searchInput.addEventListener("input", () => {
        champSearchText = searchInput.value;
        renderChampPool(p);
      });
    }

    if (isMine) wireProfileCard(container, p, false);
    wireTodos(container, p);
    const tt = document.getElementById("tierToggle"), tc = document.getElementById("tierCollapse");
    if (tt && tc) tt.addEventListener("click", () => {
      const open = tc.classList.contains("collapsed");
      try { localStorage.setItem("unc_collapse_tier", open ? "0" : "1"); } catch(e){}
      tt.setAttribute("aria-expanded", open ? "true" : "false"); tt.title = open ? "Einklappen" : "Ausklappen";
      clearTimeout(tc._t);
      if (open){ tc.classList.remove("collapsed"); tc._t = setTimeout(() => tc.classList.add("settled"), REDUCED_MOTION ? 0 : 360); }
      else { tc.classList.remove("settled"); tc.classList.add("collapsed"); }
    });

    loadChampions().then(() => {
      renderTierRows(p, isMine);
      if (isMine) renderChampPool(p);
    });
  }

  // Eigene Einstellungen auf der eigenen Spielerseite (gleiche Daten wie in der Verwaltung, die nur noch der Admin erreicht)
  function profileCardHtml(p, isAdm){
    const has = !!p.avatar;
    let h = '<section class="manage-card profile-card"><h3>' + L("Meine Einstellungen", "My settings") + '</h3>' +
      '<div class="manage-item profile-row"><span class="avatar-edit"><label class="avatar-pick" title="' + L("Profilbild hochladen", "Upload profile picture") + '">' + avatarHtml(p) + '<input type="file" accept="image/*" id="profAvatar" hidden></label>' +
      (has ? '<button class="btn small avatar-clear" type="button" id="profAvatarClear" title="' + L("Bild entfernen", "Remove picture") + '">' + ICO.x + '</button>' : '') + '</span>' +
      '<input type="text" id="profName" maxlength="30" value="' + escapeHtml(p.name || "") + '" placeholder="' + L("Name", "Name") + '">' + (isAdm ? '<strong>(Admin)</strong>' : '') + '</div>';
    if (!isAdm){
      h += '<div class="manage-item profile-row"><select id="profLane"><option value=""' + (!p.lane ? " selected" : "") + '>' + L("Rolle wählen", "Choose role") + '</option>' +
        LANES.map(l => '<option value="' + l.id + '"' + (p.lane === l.id ? " selected" : "") + '>' + l.label + '</option>').join("") + '</select>' +
        '<select id="profRole"><option value="start"' + (p.role === "start" ? " selected" : "") + '>main</option><option value="sub"' + (p.role === "sub" ? " selected" : "") + '>sub</option></select></div>' +
        '<div class="manage-item profile-row"><input type="text" class="opgg-input" id="profOpgg" placeholder="OP.GG-Link" value="' + escapeHtml(p.opgg || "") + '"></div>';
    }
    return h + '</section>';
  }
  function wireProfileCard(root, p, isAdm){
    const $ = id => root.querySelector("#" + id);
    const setField = (field, value) => { if (isAdm) setTeamField(field === "avatar" ? "adminAvatar" : "adminName", value); else updatePlayer(p.id, field, value); };
    const file = $("profAvatar");
    if (file) file.addEventListener("change", async () => {
      const f = file.files && file.files[0]; if (!f) return;
      try { setField("avatar", await resizeAvatarFile(f)); } catch(e){ uiAlert(L("Das Bild konnte nicht verarbeitet werden.", "The image could not be processed.")); }
    });
    const clr = $("profAvatarClear"); if (clr) clr.addEventListener("click", () => setField("avatar", ""));
    const nm = $("profName"); if (nm) nm.addEventListener("change", () => { const v = nm.value.trim(); if (v || isAdm) setField("name", v); else nm.value = p.name || ""; });
    if (isAdm) return;
    const ln = $("profLane"); if (ln) ln.addEventListener("change", () => updatePlayer(p.id, "lane", ln.value));
    const rl = $("profRole"); if (rl) rl.addEventListener("change", () => updatePlayer(p.id, "role", rl.value));
    const op = $("profOpgg"); if (op) op.addEventListener("change", () => updatePlayer(p.id, "opgg", op.value.trim()));
  }

  function renderTierRows(p, isMine){
    TIERS.forEach(t => {
      const dropZone = document.querySelector('[data-tier-drop="' + t + '"]');
      if (!dropZone) return;
      const champIds = tierOrderFor(p, t);
      if (!champIds.length){
        dropZone.innerHTML = '<span class="tier-empty">Noch keine Champions</span>';
      } else {
        dropZone.innerHTML = champIds.map(id => {
          const champ = CHAMPIONS.find(c => c.id === id);
          const name = champ ? champ.name : id;
          const xBtn = isMine ? '<span class="remove-x" data-remove-champ="' + id + '">' + ICO.x + '</span>' : '';
          const draggableAttr = isMine ? ' draggable="true" data-tier-champ="' + id + '"' : '';
          return '<span class="champ-icon"' + draggableAttr + ' title="' + escapeHtml(name) + '"><img src="' + championIconUrl(id) + '" alt="' + escapeHtml(name) + '" loading="lazy" draggable="false">' + xBtn + '</span>';
        }).join("");
      }
      if (isMine){
        const row = dropZone.closest(".tier-row");
        // Drop aus dem Champion-Pool (neuer Champion, kein Reihen-internes Ziehen)
        row.addEventListener("dragover", (e) => { e.preventDefault(); if (!row.classList.contains("dragover")) playDragTickSound(); row.classList.add("dragover"); });
        row.addEventListener("dragleave", () => row.classList.remove("dragover"));
        row.addEventListener("drop", (e) => {
          e.preventDefault();
          row.classList.remove("dragover");
          const champId = e.dataTransfer.getData("text/plain");
          if (!champId || champId === "reorder" || !CHAMPIONS.some(c => c.id === champId)) return;
          if (dropZone.querySelector('[data-tier-champ="' + champId + '"]')) return; // schon in dieser Reihe -> Live-Reorder übernimmt das
          setChampionTier(p.id, champId, t);
        });
        row.addEventListener("click", (e) => {
          if (e.target.closest("[data-remove-champ]")) return;
          if (selectedChamp){
            setChampionTier(p.id, selectedChamp, t);
            selectedChamp = null;
          }
        });
      }
    });
    if (isMine){
      document.querySelectorAll("[data-remove-champ]").forEach(btn => {
        btn.addEventListener("click", (e) => {
          e.stopPropagation();
          removeChampionTier(p.id, btn.dataset.removeChamp);
        });
      });
      // Live-Sortieren: springt schon beim Drüberziehen an die richtige Stelle (über Reihen hinweg),
      // committed den fertigen Zustand erst einmal ganz am Ende.
      const tierWrap = document.querySelector(".tier-list") || document.getElementById("viewPlayer");
      if (tierWrap){
        wireLiveReorder(tierWrap, "[data-tier-champ]", "[data-tier-drop]", () => {
          const orderByTier = {};
          TIERS.forEach(t => {
            const dz = document.querySelector('[data-tier-drop="' + t + '"]');
            orderByTier[t] = dz ? [...dz.querySelectorAll("[data-tier-champ]")].map(el => el.dataset.tierChamp) : [];
          });
          commitTierOrder(p.id, orderByTier);
        });
      }
    }
  }

  function renderChampPool(p){
    const grid = document.getElementById("champGrid");
    if (!grid) return;
    if (!CHAMPIONS.length){
      grid.innerHTML = '<span class="champ-loading">Champions konnten nicht geladen werden – Internetverbindung prüfen.</span>';
      return;
    }
    const search = champNorm(champSearchText);
    const assigned = new Set(Object.keys(p.tierlist || {}));
    const list = CHAMPIONS.filter(c => !assigned.has(c.id) && champNorm(c.name).includes(search));
    grid.innerHTML = list.length ? list.map(c => {
      const sel = selectedChamp === c.id ? " selected" : "";
      return '<span class="champ-icon' + sel + '" data-pool-champ="' + c.id + '" draggable="true" title="' + escapeHtml(c.name) + '"><img src="' + championIconUrl(c.id) + '" alt="' + escapeHtml(c.name) + '" loading="lazy" draggable="false"></span>';
    }).join("") : '<span class="champ-loading">Keine Treffer</span>';

    grid.querySelectorAll("[data-pool-champ]").forEach(el => {
      el.addEventListener("click", () => {
        selectedChamp = (selectedChamp === el.dataset.poolChamp) ? null : el.dataset.poolChamp;
        renderChampPool(p);
      });
      el.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData("text/plain", el.dataset.poolChamp);
      });
    });
  }

  function renderChampionsOverview(){
    const container = document.getElementById("viewChampions");
    if (!championOverviewSelected){
      championOverviewSelected = new Set(activePlayers().filter(p => p.role === "start").map(p => p.id));
    }

    const me = getMe();
    const targetPlayer = (me && playerById(me)) ? me : (activePlayers()[0] ? activePlayers()[0].id : null);

    let html = '<div class="nav-links"><a href="#" class="back-link">' + ICO.left + ' Hauptseite</a>';
    if (targetPlayer){
      html += '<a href="#player/' + encodeURIComponent(targetPlayer) + '" class="back-link">Spieleransicht ' + ICO.right + '</a>';
    }
    html += '</div>';
    html += '<h2 class="section-heading">Spielerübersicht</h2>';
    html += '<div class="player-toggle-row" id="playerToggleRow">';
    activePlayers().forEach(p => {
      const on = championOverviewSelected.has(p.id);
      html += '<button type="button" class="toggle-chip' + (on ? " on" : "") + '" data-toggle-player="' + p.id + '">' + (laneById(p.lane) ? '<img class="role-icon" src="' + laneById(p.lane).icon + '" alt="">' : '') + escapeHtml(p.name || "—") + '</button>';
    });
    html += '</div>';
    html += '<div class="champions-grid" id="championsGrid"><span class="champ-loading">Lädt…</span></div>';

    container.innerHTML = html;

    container.querySelector(".back-link").addEventListener("click", (e) => {
      e.preventDefault();
      location.hash = "";
    });
    container.querySelectorAll("[data-toggle-player]").forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.togglePlayer;
        if (championOverviewSelected.has(id)) championOverviewSelected.delete(id);
        else championOverviewSelected.add(id);
        renderChampionsOverview();
      });
    });

    loadChampions().then(() => renderChampionsGrid());
  }

  function renderChampionsGrid(){
    const grid = document.getElementById("championsGrid");
    if (!grid) return;
    const selected = activePlayers().filter(p => championOverviewSelected.has(p.id));
    if (!selected.length){
      grid.innerHTML = '<div class="visually-empty">Keine Spieler ausgewählt.</div>';
      return;
    }
    grid.innerHTML = selected.map(p => {
      let card = '<div class="compact-card">';
      card += '<div class="compact-card-head"><a href="#player/' + encodeURIComponent(p.id) + '" class="compact-card-name">' + (laneById(p.lane) ? '<img class="role-icon" src="' + laneById(p.lane).icon + '" alt="">' : '') + escapeHtml(p.name || "—") + '</a>' +
        (safeHref(p.opgg) ? '<a href="' + escapeHtml(safeHref(p.opgg)) + '" target="_blank" rel="noopener noreferrer" class="opgg-link" title="OP.GG-Profil von ' + escapeHtml(p.name) + '"><img src="' + ICON_OPGG + '" alt="OP.GG"></a>' : '') +
        '</div>';
      TIERS.forEach(t => {
        const ids = Object.keys(p.tierlist || {}).filter(id => p.tierlist[id] === t);
        card += '<div class="compact-tier-row"><span class="tier-label small ' + t.toLowerCase() + '">' + t + '</span><div class="compact-tier-champs">';
        if (!ids.length){
          card += '<span class="tier-empty small">–</span>';
        } else {
          card += ids.map(id => {
            const champ = CHAMPIONS.find(c => c.id === id);
            const name = champ ? champ.name : id;
            return '<img class="compact-champ" src="' + championIconUrl(id) + '" alt="' + escapeHtml(name) + '" title="' + escapeHtml(name) + '" loading="lazy">';
          }).join("");
        }
        card += '</div></div>';
      });
      card += '</div>';
      return card;
    }).join("");
  }

  // ---------- Weiche Übergänge (nur UI) ----------
  const REDUCED_MOTION = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function slideAnim(el, show, cb){
    if (!el || !el.animate || REDUCED_MOTION){ if (cb) cb(); return; }
    const cs = getComputedStyle(el);
    const full = { height: cs.height, opacity: 1, paddingTop: cs.paddingTop, paddingBottom: cs.paddingBottom, marginTop: cs.marginTop, marginBottom: cs.marginBottom };
    const zero = { height: "0px", opacity: 0, paddingTop: "0px", paddingBottom: "0px", marginTop: "0px", marginBottom: "0px" };
    const prev = el.style.overflow;
    el.style.overflow = "hidden";
    const a = el.animate(show ? [zero, full] : [full, zero], { duration: show ? 260 : 220, easing: "ease-in-out", fill: show ? "none" : "forwards" });
    a.onfinish = () => { el.style.overflow = prev; if (cb) cb(); try { a.cancel(); } catch(e){} };
    a.oncancel = () => { el.style.overflow = prev; };
  }
  function fadeIn(els, dy){
    if (REDUCED_MOTION) return;
    [].concat(els).forEach((el, i) => {
      if (el && el.animate) el.animate([{ opacity: 0, transform: "translateY(" + (dy == null ? -6 : dy) + "px)" }, { opacity: 1, transform: "none" }], { duration: 260, delay: Math.min(i, 6) * 20, easing: "ease-out", fill: "backwards" });
    });
  }
  function fadeOut(els, cb){
    const list = [].concat(els).filter(Boolean);
    if (REDUCED_MOTION || !list.length || !list[0].animate){ cb(); return; }
    let a;
    list.forEach(el => { a = el.animate([{ opacity: 1, transform: "none" }, { opacity: 0, transform: "translateY(-4px)" }], { duration: 150, easing: "ease-in", fill: "forwards" }); });
    a.onfinish = cb;
  }
