  function openRescheduleModal(matchdayId, proposalId){
    const md = (state.matchdays || []).find(m => m.id === matchdayId);
    const r = md ? (md.reschedule || []).find(r => (r.id || r.playerId) === proposalId) : null;
    if (!md || !r){
      closeModal();
      return;
    }
    openModalTarget = { kind: "reschedule", matchdayId, proposalId };

    const me = getMe();
    const proposer = playerById(r.playerId);
    const votes = r.votes || {};
    const yesVotes = countVotes(votes, "yes");
    const modalGreen = yesVotes >= 5 ? " green" : "";
    const overlay = document.getElementById("modalOverlay");
    const box = document.getElementById("modalBox");

    let html = '<div class="modal-head"><h3>Terminvorschlag</h3><button class="modal-close" id="modalCloseBtn" type="button">' + ICO.x + '</button></div>';
    const canEditReason = !!me && (r.playerId === me || isAdmin());
    html += '<p class="modal-proposal">' + escapeHtml(proposer ? proposer.name : "?") + ' schlägt vor:</p>';
    html += canEditReason
      ? '<input type="text" class="modal-reason-input' + modalGreen + '" id="reasonInput" value="' + escapeHtml(r.reason || "") + '" placeholder="Termin, z. B. 04.10. 19 Uhr">'
      : '<p class="modal-proposal-text' + modalGreen + '">' + escapeHtml(r.reason || "–") + '</p>';
    html += '<div class="modal-sub">' + escapeHtml(md.label) + (md.opponent ? " · vs " + escapeHtml(md.opponent) : "") + '</div>';

    html += '<div class="modal-section-title">Abstimmung</div>';
    html += '<div class="modal-votes">';
    const voteMeta = r.voteMeta || {};
    activePlayers().forEach(p => {
      const v = votes[p.id];
      const meta = voteMeta[p.id] || {};
      const canVoteFor = !!me && (p.id === me || isAdmin());
      const disabledAttr = canVoteFor ? "" : " disabled";
      const maybeMark = meta.maybe ? ' <span class="vote-maybe-mark" title="War ursprünglich \'unsicher\'">?</span>' : '';
      const noteLine = meta.note ? '<div class="note-line">„' + escapeHtml(meta.note) + '“</div>' : '';
      html += '<div class="vote-row"><span>' + escapeHtml(p.name || "—") + maybeMark + '</span><div class="vote-btns">'
        + '<button class="vbtn' + (v === "yes" ? " active yes" : "") + '" data-vote-player="' + p.id + '" data-vote="yes" type="button"' + disabledAttr + '>' + ICO.check + '</button>'
        + '<button class="vbtn' + (v === "no" ? " active no" : "") + '" data-vote-player="' + p.id + '" data-vote="no" type="button"' + disabledAttr + '>' + ICO.x + '</button>'
        + '</div></div>' + noteLine;
    });
    html += '</div>';

    html += '<div class="modal-section-title">Status</div>';
    html += '<label class="modal-check"><input type="checkbox" id="chkRequested" ' + (r.requestedWithOpponent ? "checked" : "") + '> Beim Gegner-Team angefragt</label>';
    html += '<div class="modal-outcome">' +
      '<button type="button" class="outcome-btn' + (!r.accepted && !r.rejected ? " on" : "") + '" data-outcome="">Offen</button>' +
      '<button type="button" class="outcome-btn yes' + (r.accepted ? " on" : "") + '" data-outcome="accepted">' + ICO.check + ' Angenommen</button>' +
      '<button type="button" class="outcome-btn no' + (r.rejected ? " on" : "") + '" data-outcome="rejected">' + ICO.x + ' Abgelehnt</button>' +
      '</div>';

    const parsedForSwap = parseProposalDate(r.reason);
    if (parsedForSwap && parsedForSwap.hasTime && me){
      html += '<div class="modal-section-title">Übernehmen</div>';
      html += '<button class="btn small ghost" id="swapBtn" type="button">Als offiziellen Termin übernehmen</button>';
    }

    box.innerHTML = html;
    overlay.style.display = "flex";

    document.getElementById("modalCloseBtn").addEventListener("click", closeModal);

    if (document.getElementById("swapBtn")){
      document.getElementById("swapBtn").addEventListener("click", () => {
        uiConfirm("Diesen Termin als offiziellen Spieltag-Termin übernehmen? Der bisherige Termin wird dafür zu einem neuen Terminvorschlag.", { ok: L("Übernehmen", "Apply") }).then(o => {
          if (o){ swapMatchdayDate(matchdayId, proposalId); closeModal(); }
        });
      });
    }

    if (canEditReason){
      document.getElementById("reasonInput").addEventListener("change", (e) => {
        setRescheduleStatus(matchdayId, proposalId, "reason", e.target.value);
      });
    }

    box.querySelectorAll("[data-vote-player]").forEach(btn => {
      btn.addEventListener("click", () => {
        voteOnReschedule(matchdayId, proposalId, btn.dataset.votePlayer, btn.dataset.vote);
      });
    });
    document.getElementById("chkRequested").addEventListener("change", (e) => {
      setRescheduleStatus(matchdayId, proposalId, "requestedWithOpponent", e.target.checked);
    });
    box.querySelectorAll("[data-outcome]").forEach(btn => {
      btn.addEventListener("click", () => {
        setRescheduleOutcome(matchdayId, proposalId, btn.dataset.outcome);
      });
    });
  }

