  // ---------- OP.GG: Name/Tag aus dem Link lesen, Multi-Suche bauen ----------
  let draftEditingLinks = new Set(); // "rolle:art" (art = pl | opgg) der Link-Felder, die gerade bearbeitet werden (nur UI-Zustand)

  function safeHref(url){
    const s = String(url || "").trim();
    return /^https?:\/\//i.test(s) ? s : "";
  }
  function withProtocol(s){ return /^https?:\/\//i.test(s) ? s : "https://" + s; }

  // erkennt z. B. https://www.op.gg/summoners/euw/Name-TAG  und  https://op.gg/de/lol/summoners/euw/name-187
  function parseOpgg(url){
    if (!url) return null;
    const s = String(url).trim();
    const m = s.match(/^(?:https?:\/\/)?(?:[a-z0-9-]+\.)*op\.gg\/(?:[a-z]{2}\/)?(?:lol\/)?summoners\/([a-z0-9]+)\/([^\/?#]+)/i);
    if (!m) return null;
    let raw = m[2].replace(/\+/g, " ");
    try { raw = decodeURIComponent(raw); } catch (e) {}
    const i = raw.lastIndexOf("-");
    if (i <= 0 || i === raw.length - 1) return null;
    return { region: m[1].toLowerCase(), name: raw.slice(0, i).normalize("NFC"), tag: raw.slice(i + 1).normalize("NFC"), url: withProtocol(s) };
  }
  // erkennt z. B. https://www.primeleague.gg/de/users/2264349-philipppatronum  ->  Name = "philipppatronum"
  function parsePrimeLeague(url){
    if (!url) return null;
    const s = String(url).trim();
    const m = s.match(/^(?:https?:\/\/)?(?:[a-z0-9-]+\.)*primeleague\.gg\/(?:[a-z]{2}\/)?users\/(\d+)(?:-([^\/?#]+))?/i);
    if (!m) return null;
    let name = m[2] ? m[2].replace(/\+/g, " ") : "";
    try { name = decodeURIComponent(name); } catch (e) {}
    return { id: m[1], name: (name || ("Profil " + m[1])).normalize("NFC"), url: withProtocol(s) };
  }
  // Format: .../multisearch/euw?summoners=Name1%23TAG1%2CName2%23TAG2   (%23 = #, %2C = Trennzeichen, + = Leerzeichen)
  function opggMultiUrl(entries){
    if (!entries.length) return "";
    const region = entries[0].region || "euw";
    const list = entries.map(e => encodeURIComponent(e.name + "#" + e.tag).replace(/%20/g, "+")).join("%2C");
    return "https://op.gg/de/lol/multisearch/" + region + "?summoners=" + list;
  }
